package piglatin

import "strings"

const vowels = "aeiou"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

func word(w string) string {
	if isVowel(w[0]) || strings.HasPrefix(w, "xr") || strings.HasPrefix(w, "yt") {
		return w + "ay"
	}

	// Find the end of the leading consonant cluster.
	i := 0
	for i < len(w) {
		c := w[i]
		if isVowel(c) {
			break
		}
		// Rule 4: a "y" after at least one consonant acts like a vowel.
		if c == 'y' && i > 0 {
			break
		}
		// Rule 3: a "qu" at the end of the cluster moves together with it.
		if c == 'q' && i+1 < len(w) && w[i+1] == 'u' {
			i += 2
			break
		}
		i++
	}
	return w[i:] + w[:i] + "ay"
}

func isVowel(c byte) bool {
	return strings.IndexByte(vowels, c) >= 0
}
